
(function(){
const {authLogin,authLogout,getSession,ensureSession,query,mutate,uploadMedia,renderMedia,safeUrl} = window.CFAPI;
const copySection=(x)=>x==null?null:JSON.parse(JSON.stringify(x));
const app=document.querySelector('#app');let pages=[],sections=[],activePage=null,activeSection=null,tab='contenido',admin=null,dirty=false,allLeads=[];
const SOURCE_NAMES={'31127e24-141e-4252-bd84-df898283014f':'Inicio → Camina por Cuba','a7fad714-dc88-4891-a900-dc60fa34ffe1':'Inicio → Iniciativas','9d435fe7-26c9-4d6a-9e61-20a3780a2f8e':'Inicio → Casa Luz','d0625afa-17e5-444e-83a9-a3a9a70d0d7d':'Inicio → Plétora','18111801-feb6-4f13-9bef-ff338258b3cd':'Inicio → Gotas de Felicidad'};
const t=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const key=x=>String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const notify=(msg,bad=false)=>{const n=document.getElementById('toast');if(!n)return;n.textContent=msg;n.className='toast '+(bad?'bad':'good');n.hidden=false;clearTimeout(window.msgTimer);window.msgTimer=setTimeout(()=>n.hidden=true,5500)};
const TEMPLATE_LABELS={hero:'Portada',manifesto:'Texto + imagen',walk:'Camina por Cuba / tarjetas',cards:'Tarjetas',quote:'Frase destacada',split:'Imagen + texto',cta:'Llamada a la acci\u00f3n',donations:'Gotas de Felicidad',faq:'Preguntas frecuentes',content:'Contenido simple'};
function sectionIsVisible(s){return s?.status==='published'&&s?.settings?.show_on_page!==false}
function badge(status){return `<span class="state ${status==='published'?'published':'draft'}">${status==='published'?'Publicado':'Borrador'}</span>`}
function field(title,val,bind,type='text',rows=4){if(type==='textarea')return `<label class="field"><span>${title}</span><textarea rows="${rows}" data-bind="${bind}">${t(val)}</textarea></label>`;return `<label class="field"><span>${title}</span><input type="${type}" value="${t(val)}" data-bind="${bind}"></label>`}
function mediaFields(media,scope){const isVideo=media?.type==='video';return `<div class="media-editor"><div class="preview-mini">${renderMedia(media)}</div><div class="editor-fields"><label class="field"><span>Tipo de medio</span><select data-bind="${scope}.type"><option value="image" ${!isVideo?'selected':''}>Imagen</option><option value="video" ${isVideo?'selected':''}>Video</option></select></label>${field('URL de imagen, video, YouTube o Vimeo',media?.url,scope+'.url')}<label class="field upload-box"><span>Subir archivo de imagen o video</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif,video/mp4,video/webm" data-upload="${scope}"><small>Archivos de hasta 50 MB. Se almacenan en Supabase Storage.</small></label><div class="video-poster-settings" ${isVideo?'':'hidden'}><h4>Miniatura / portada del video</h4><small>Recomendado: imagen horizontal 16:9 (1280 x 720 px). La miniatura se ve antes de pulsar reproducir. Si usas YouTube y no eliges una, se intenta mostrar la de YouTube.</small>${field('URL de la miniatura (imagen JPG, PNG, WEBP)',media?.poster||'',scope+'.poster')}<label class="field upload-box"><span>Subir una miniatura desde tu computadora</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-upload-poster="${scope}"><small>La imagen se almacena en Supabase. Guarda o publica la seccion luego de subirla.</small></label></div><label class="field"><span>Encuadre de imagen o miniatura</span><select data-bind="${scope}.position">${['center','top','bottom'].map(x=>`<option ${media?.position===x?'selected':''} value="${x}">${x}</option>`).join('')}</select></label></div></div>`}

function cfAdminPurposePhotos(s){
 const gal=s.settings?.manifesto_gallery;
 if(Array.isArray(gal))return gal;
 const m=s.media||{};
 return m.url?[{url:m.url,focal_y:m.position==='top'?25:m.position==='bottom'?75:50}]:[];
}
function cfAdminPurposeFields(s){
 if(!Array.isArray(s.settings?.manifesto_gallery))s.settings.manifesto_gallery=cfAdminPurposePhotos(s);
 const gallery=s.settings.manifesto_gallery;
 return '<div class="edit-head"><h3>Carrusel de Propósito · Fotos 9:16</h3><p>La caja conserva su tamaño vertical con cúpula superior. Sube fotos 9:16, ordénalas y ajusta el encuadre de cada una. Los cambios aparecen al publicar.</p></div>'+
 '<div class="two-col"><label class="field"><span>Reproducción automática</span><select data-bind="settings.manifesto_autoplay"><option value="true" '+(String(s.settings.manifesto_autoplay??'true')==='false'?'':'selected')+'>Activada</option><option value="false" '+(String(s.settings.manifesto_autoplay)==='false'?'selected':'')+'>Desactivada</option></select></label>'+
 field('Segundos entre fotografías (2 a 15)',s.settings?.manifesto_interval??5,'settings.manifesto_interval','number')+'</div>'+
 gallery.map((m,i)=>'<div class="item-editor" style="margin:12px 0"><div class="item-bar"><strong>Fotografía '+(i+1)+' · Formato recomendado 9:16</strong><div><button type="button" class="tiny" data-gallery-up="'+i+'" '+(i===0?'disabled':'')+'>↑</button><button type="button" class="tiny" data-gallery-down="'+i+'" '+(i===gallery.length-1?'disabled':'')+'>↓</button><button type="button" class="tiny danger" data-gallery-remove="'+i+'">Eliminar</button></div></div>'+
 (safeUrl(m.url)?'<div class="preview-mini" style="width:145px;height:200px;border-radius:75px 75px 10px 10px;overflow:hidden"><img style="width:100%;height:100%;object-fit:cover;object-position:center '+Math.min(100,Math.max(0,Number(m.focal_y??50)||0))+'%" src="'+t(safeUrl(m.url))+'" alt="Vista previa foto '+(i+1)+'"></div>':'')+
 field('URL de la fotografía 9:16',m.url||'','settings.manifesto_gallery.'+i+'.url')+
 '<label class="field upload-box"><span>Subir fotografía 9:16</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-upload="settings.manifesto_gallery.'+i+'"><small>PNG, JPG, WEBP o AVIF. Preferiblemente 1080 × 1920.</small></label>'+
 field('Punto focal vertical (0 superior a 100 inferior)',m.focal_y??50,'settings.manifesto_gallery.'+i+'.focal_y','number')+'</div>').join('')+
 '<button type="button" class="control outlined full" id="addPurposePhoto">+ Agregar fotografía al carrusel</button>'+
 '<p class="auth-note">El desplazamiento se detiene al pasar el mouse o interactuar. En dispositivos con movimiento reducido, el pase automático queda desactivado.</p>';
}
function buttonsEditor(bs,scope){return `<div class="stack">${(bs||[]).map((b,i)=>`<div class="mini-card"><div class="mini-head"><strong>Bot\u00f3n ${i+1}</strong><div><button class="tiny" data-move-button="${scope}:${i}:-1" title="Subir">\u2191</button><button class="tiny" data-move-button="${scope}:${i}:1" title="Bajar">\u2193</button><button class="tiny danger" data-remove-button="${scope}:${i}" title="Eliminar">\u00d7</button></div></div><div class="two-col">${field('Texto del bot\u00f3n',b.label,scope+'.'+i+'.label')}${field('Destino (URL, p\u00e1gina o #secci\u00f3n)',b.href,scope+'.'+i+'.href')}</div><label class="field"><span>Estilo</span><select data-bind="${scope}.${i}.style">${[['primary','Principal morado'],['secondary','Secundario contorno'],['ghost','Amarillo']].map(v=>`<option value="${v[0]}" ${b.style===v[0]?'selected':''}>${v[1]}</option>`).join('')}</select></label></div>`).join('')}</div><button class="control outlined" data-add-button="${scope}">+ Agregar bot\u00f3n</button>`}

/* Un contacto independiente para cada tarjeta de la sección 5. */
function initiativeWhatsappField(item,i){
 const path='items.'+i+'.whatsapp_number';
 return field('WhatsApp de '+(item.title||'esta iniciativa')+' (con indicativo del país)',item.whatsapp_number||'',path,'tel');
}
function initiativeWhatsappFields(s){
 if(s.section_key!=='iniciativas')return '';
 return '<div class="edit-head"><h3>Contactos WhatsApp de las seis iniciativas</h3><p>Escribe un número distinto por iniciativa, incluyendo el código del país (por ejemplo, +53 o +1). Déjalo vacío si todavía no tienes el contacto. Guardar estos números no cambia los botones públicos; sus enlaces se configurarán al desarrollar cada página.</p></div>'+
 (s.items||[]).map((item,i)=>initiativeWhatsappField(item,i)).join('');
}
/* Fotografía individual de las tres facilitadoras de Eligiendo Milagros. */
function mentorPhotoFields(item,i){
 const scope='items.'+i+'.media';
 const media=item.media||{type:'image',url:'',position:'center'};
 const preview=media.url&&media.type!=='video'?'<img src="'+t(safeUrl(media.url))+'" alt="Vista previa de '+t(item.title)+'" style="width:100%;height:100%;object-fit:cover;border-radius:9px">':'<div class="missing-media" style="min-height:160px;display:grid;place-items:center">Fotografía pendiente</div>';
 return '<div class="media-editor"><div class="preview-mini" style="min-height:175px">'+preview+'</div><div class="editor-fields">'+
 '<p class="auth-note">Fotografía independiente de '+t(item.title)+'. Recomendado: vertical 4:5, JPG, PNG o WebP. Se mostrará encima de su biografía cuando publiques.</p>'+
 field('URL de la fotografía',media.url||'',scope+'.url')+
 '<label class="field upload-box"><span>Subir fotografía de '+t(item.title)+'</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-upload="'+scope+'"><small>Sube una fotografía desde tu equipo; queda almacenada en Supabase. Después pulsa Publicar cambios.</small></label>'+
 '<label class="field"><span>Encuadre de la fotografía</span><select data-bind="'+scope+'.position">'+['center','top','bottom'].map(x=>'<option value="'+x+'" '+((media.position||'center')===x?'selected':'')+'>'+({center:'Centro',top:'Superior',bottom:'Inferior'}[x])+'</option>').join('')+'</select></label>'+
 (media.url?'<button type="button" class="control outlined" data-clear-mentor-photo="'+i+'">Quitar fotografía de '+t(item.title)+'</button>':'')+
 '</div></div>';
}
function cardEditor(item,i){if(item.shared_from_section)return `<div class="item-synced"><div class="item-bar"><strong>${String(i+1).padStart(2,'0')} · ${t(item.title)} · Contenido vinculado</strong><div><button type="button" class="tiny" data-card-up="${i}" title="Subir esta tarjeta" aria-label="Subir ${t(item.title)}">↑</button><button type="button" class="tiny" data-card-down="${i}" title="Bajar esta tarjeta" aria-label="Bajar ${t(item.title)}">↓</button></div></div><p>El texto, video y miniatura se administran en ${t(SOURCE_NAMES[item.shared_from_section]||'la sección de origen')}.</p><button type="button" class="control outlined" data-edit-source="${t(item.shared_from_section)}">↗ Editar contenido de origen</button>${activeSection?.section_key==='iniciativas'?initiativeWhatsappField(item,i):''}<h4>Botones locales de esta tarjeta</h4>${buttonsEditor(item.buttons||[],`items.${i}.buttons`)}</div>`;return `<div class="item-editor"><div class="item-bar"><strong>${String(i+1).padStart(2,'0')} \u00b7 ${t(item.title||'Nueva tarjeta')}</strong><div><button class="tiny" data-card-up="${i}">\u2191</button><button class="tiny" data-card-down="${i}">\u2193</button><button class="tiny" data-card-clone="${i}">Duplicar</button><button class="tiny danger" data-card-remove="${i}">Eliminar</button></div></div><div class="two-col">${field('T\u00edtulo',item.title,`items.${i}.title`)}${field('Etiqueta auxiliar',item.meta,`items.${i}.meta`)}</div>${field('Descripci\u00f3n',item.body,`items.${i}.body`,'textarea',3)}${activeSection?.section_key==='detail-eligiendo-milagros-2'?'<h4>Fotografía de '+t(item.title)+'</h4>'+mentorPhotoFields(item,i):'<h4>Imagen o video</h4>'+mediaFields(item.media||{},`items.${i}.media`)}${activeSection?.section_key==='iniciativas'?initiativeWhatsappField(item,i):''}<h4>Botones de la tarjeta</h4>${buttonsEditor(item.buttons||[],`items.${i}.buttons`)}</div>`}
function loginScreen(message=''){app.innerHTML=`<div class="auth-background"><div class="auth-pane"><div class="auth-brand">${window.CF_LOGO_HTML()}</div><div class="auth-mark">${window.CF_ASTERISK_SVG}</div><h1>Un espacio para hacer crecer el movimiento.</h1><p>Administra el contenido, las im\u00e1genes, las iniciativas y cada secci\u00f3n de Cuba Feliz.</p><div class="auth-note">Una Cuba feliz primero nace en mi coraz\u00f3n.</div></div><div class="auth-form-wrap"><form id="loginForm" class="login-form"><div class="chip">ACCESO SEGURO</div><h2>Bienvenido de nuevo</h2><p>Inicia sesi\u00f3n con tu usuario autorizado.</p><label>Correo electr\u00f3nico<input type="email" name="email" required autocomplete="username" placeholder="correo@empresa.com"></label><label>Contrase\u00f1a<input type="password" name="password" required autocomplete="current-password" placeholder="Tu contrase\u00f1a"></label><button type="submit" class="control primary full">Ingresar al dashboard \u2197</button><p class="auth-error" role="alert">${t(message)}</p><a href="#pagina/inicio">\u2190 Ver el sitio p\u00fablico</a></form></div></div>`;window.CF_NAV_NOTIFY?.(app);const form=document.getElementById('loginForm');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;b.textContent='Verificando...';try{await authLogin(form.elements.email.value,form.elements.password.value);await loadAdmin()}catch(err){b.disabled=false;b.textContent='Ingresar al dashboard \u2197';form.querySelector('.auth-error').textContent=err.message}}}
async function loadAdmin(){try{await ensureSession();if(!getSession())return loginScreen();const a=await query('cf_admins','select=*&user_id=eq.'+encodeURIComponent(getSession().user.id),{auth:true});if(!a.length||!a[0].active)return loginScreen('Esta cuenta no tiene permisos administrativos.');admin=a[0];pages=await query('cf_pages','select=*&order=sort_order.asc',{auth:true});if(!pages.length)throw Error('No se encontraron p\u00e1ginas');activePage=pages.find(p=>p.id===activePage?.id)||pages.find(p=>p.slug==='inicio')||pages[0];await loadPage(activePage.id)}catch(e){console.error(e);loginScreen('No fue posible cargar el dashboard. '+e.message)}}
async function loadPage(pid,keepSelection=false){if(dirty&&!confirm('Hay cambios sin guardar. \u00bfContinuar y descartarlos?'))return;activePage=pages.find(x=>x.id===pid);sections=await query('cf_sections','select=*&page_id=eq.'+pid+'&order=sort_order.asc',{auth:true});if(activePage?.slug==='inicio')window.CF_LOGO_URL=sections.find(x=>x.section_key==='home')?.settings?.logo_url||'assets/cuba-feliz-logo-oficial.png';activeSection=copySection(keepSelection?sections.find(x=>x.id===activeSection?.id)||sections[0]:sections[0]||null);tab=activeSection?.section_key==='home'?'franjas':'contenido';dirty=false;draw()}
function draw(){app.innerHTML=`<div class="admin-app"><aside class="sidebar"><a href="#pagina/inicio" class="side-brand" target="_blank">${window.CF_LOGO_HTML()}</a><div class="side-label">SITIO WEB</div><nav class="pages-nav">${pages.map(p=>`<button class="page-link ${activePage?.id===p.id?'active':''}" data-page="${p.id}"><span class="page-icon">${p.slug==='inicio'?'\u2302':'\u25a6'}</span><span>${t(p.title)}</span>${p.status==='published'?'<i class="green-dot"></i>':''}</button>`).join('')}</nav><button class="add-page" id="newPage">+ Nueva p\u00e1gina</button><button class="page-link" id="editHomeBands"><span class="page-icon">✎</span> Franjas del Home · 1 y 2</button><div class="side-label">GESTI\u00d3N</div><button class="page-link" id="leadView"><span class="page-icon">\u2637</span> Inscripciones</button><div class="side-foot"><div class="admin-avatar">N</div><div><strong>NOVOeia</strong><small>${t(getSession()?.user?.email||'Owner')}</small></div><button id="logout" title="Salir">\u21aa</button></div></aside><div class="work-area"><header class="topbar"><div><div class="breadcrumb">SITIO WEB / ${t(activePage?.title||'Inicio')}</div><h1>Editor de contenido <span class="status-small">V5</span></h1></div><div class="top-actions"><a class="control outlined" href="#pagina/${encodeURIComponent(activePage.slug)}" target="_blank">\u2197 Vista p\u00fablica</a><button class="control primary" id="topSave" ${activeSection?'':'disabled'}>Guardar en Supabase</button></div></header><div class="editor-layout"><div class="sections-panel"><div class="panel-title"><div><h2>Secciones</h2><p>Cada interruptor controla una sección de forma independiente.</p></div></div><div class="page-badge">${t(activePage.title)} ${badge(activePage.status)}</div><div class="section-list">${sections.map((s,i)=>`<div class="section-row ${activeSection?.id===s.id?'active':''} ${sectionIsVisible(s)?'':'section-hidden'}"><button class="section-main" data-section="${s.id}"><span class="s-num">${String(i+1).padStart(2,'0')}</span><span class="s-text"><b>${t(s.title||TEMPLATE_LABELS[s.template])}</b><small>${t(TEMPLATE_LABELS[s.template])} ${s.items?.length?'\u00b7 '+s.items.length+' elementos':''}</small></span></button><div class="section-controls"><button type="button" role="switch" data-visibility-id="${s.id}" aria-checked="${sectionIsVisible(s)?'true':'false'}" aria-label="${sectionIsVisible(s)?'Ocultar':'Mostrar'} ${t(s.title||TEMPLATE_LABELS[s.template])}" class="section-visibility-switch ${sectionIsVisible(s)?'on':'off'}" title="Mostrar u ocultar solamente esta sección"><span class="switch-track"><span class="switch-knob"></span></span><span>${sectionIsVisible(s)?'Visible':'Oculta'}</span></button><div class="section-arrows"><button title="Subir" data-move="${s.id}:-1">\u2191</button><button title="Bajar" data-move="${s.id}:1">\u2193</button><button title="Clonar secci\u00f3n" data-clone="${s.id}">\u2398</button></div></div></div>`).join('')||'<div class="empty-small">Todav\u00eda no hay secciones.</div>'}</div><button class="control add-section" id="addSection">+ Agregar secci\u00f3n</button><div class="page-options"><h4>Configuraci\u00f3n de p\u00e1gina</h4><label class="field"><span>Nombre de p\u00e1gina</span><input id="pageTitle" value="${t(activePage.title)}"></label><label class="field"><span>Estado de la p\u00e1gina completa (independiente de las secciones)</span><select id="pageStatus"><option value="published" ${activePage.status==='published'?'selected':''}>Publicada</option><option value="draft" ${activePage.status==='draft'?'selected':''}>Borrador / Oculta</option></select></label><label class="toggle-row"><input type="checkbox" id="pageNav" ${activePage.show_in_nav?'checked':''}> Visible en navegaci\u00f3n</label><button class="control outlined full" id="savePage">Guardar p\u00e1gina</button></div></div><div class="edit-panel">${activeSection?editorHtml(activeSection):'<div class="empty"><h2>Elige una secci\u00f3n</h2><p>O crea una nueva secci\u00f3n para comenzar.</p></div>'}</div></div></div><div id="toast" class="toast" hidden></div></div>`;window.CF_NAV_NOTIFY?.(app);wire()}
function editorHtml(s){const master=s.settings?.shared_items_from||s.settings?.shared_fields_from||s.settings?.shared_amounts_from;const note=master?`<div class="sync-note"><div><b>🔗 Contenido sincronizado</b><p>Fuente única: ${t(SOURCE_NAMES[master]||'sección original')}. Los cambios allí se verán también aquí, con otro diseño.</p></div><button class="control outlined" type="button" data-edit-source="${t(master)}">Editar fuente ↗</button></div>`:'';return `<div class="editor-top"><div><div class="eyebrow-small">EDITANDO SECCI\u00d3N <span>${t(TEMPLATE_LABELS[s.template])}</span></div><h2>${t(s.title||'Nueva secci\u00f3n')}</h2></div>${badge(s.status)}</div>${note}<div class="editor-tabs">${s.section_key==='home'?`<button data-tab="franjas" class="${tab==='franjas'?'active':''}">Franjas del Home · 1 y 2</button>`:''}${[['contenido','Contenido'],['multimedia',s.section_key==='camina'?'Video destacado':'Multimedia'],['tarjetas','Tarjetas / elementos'],['botones','Botones'],['historial','Historial']].map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${v}</button>`).join('')}</div><div class="editor-body">${tab==='franjas'&&s.section_key==='home'?`<div class="edit-head"><h3>1 · Franja morada superior</h3><p>Texto sobre el menú, en la parte más alta de la web.</p></div>${field('Mensaje de la franja morada (1)',s.settings?.banner_text??'La felicidad también se construye entre todos','settings.banner_text','textarea',2)}<div class="edit-head"><h3>2 · Franja amarilla debajo de la foto</h3><p>Todos los textos de esta franja y su botón se pueden cambiar aquí.</p></div>${field('Texto pequeño arriba del título (2)',s.settings?.rail_eyebrow??'Tu momento de conexión · Acceso directo','settings.rail_eyebrow')}${field('Texto principal de la franja amarilla (2)',s.settings?.rail_text??'Una meditación para compartir el presente.','settings.rail_text','textarea',3)}${field('Texto del botón de la franja amarilla',s.settings?.rail_button??'Conocer Camina por Cuba','settings.rail_button')}${field('Destino del botón de la franja amarilla',s.settings?.rail_href??'camina-por-cuba.html','settings.rail_href')}<p class="auth-note">Después de editar, pulsa <b>Publicar cambios</b>. Se guarda en Supabase y aparece al actualizar la web pública.</p>`:''}${tab==='contenido'?`<div class="edit-head"><h3>Textos y encabezados</h3><p>Guarda y publica para ver los cambios al recargar la web. Un borrador se oculta al público.</p></div>${field('Nombre interno de secci\u00f3n',s.section_key,'section_key')}${field('Etiqueta superior',s.eyebrow,'eyebrow')}${s.settings?.shared_fields_from?'<p class="auth-note">El título, subtítulo, párrafo y multimedia están vinculados a la sección principal; edítalos desde la fuente para evitar duplicaciones.</p>':`${s.section_key==='camina-banner'?field('Texto principal (una línea por renglón)',s.title,'title','textarea',4):field('Título principal',s.title,'title')}${field('Subtítulo',s.subtitle,'subtitle','textarea',2)}${field('Párrafo / texto de la sección',s.body,'body','textarea',8)}${field('Palabras del título en color destacado (exactamente como aparecen en el título)',s.settings?.title_highlight||'','settings.title_highlight')}${s.section_key==='home'?`<div class="edit-head"><h3>Fotografía e identidad de la portada</h3><p>Los textos marcados 1 y 2 se editan desde la pestaña <b>Franjas del Home</b>.</p></div>${field('Altura de la portada Home (píxeles 650 a 1050)',s.settings?.home_hero_height??830,'settings.home_hero_height','number')}${field('Encuadre vertical de la foto (0 arriba, 50 centro, 100 abajo)',s.settings?.home_photo_focus??43,'settings.home_photo_focus','number')}${field('Transparencia del asterisco (0 a 0.45)',s.settings?.home_asterisk_opacity??.18,'settings.home_asterisk_opacity')}${field('Mostrar asterisco: true o false',s.settings?.home_brand_overlay??'true','settings.home_brand_overlay')}${field('URL del logo original aprobado',s.settings?.logo_url||'assets/cuba-feliz-logo-oficial.png','settings.logo_url')}<label class="field upload-box"><span>Subir el logo oficial PNG o WebP</span><input type="file" accept="image/png,image/webp" data-upload-logo><small>Luego pulsa Publicar cambios.</small></label>`:''}`}${s.section_key==='camina-banner'?`<div class="edit-head"><h3>Franja Camina por Cuba · fecha y hora</h3><p>El logo se cambia en la pestaña Multimedia. El título se muestra en blanco y amarillo y el subtítulo es el gran «¡Dale!».</p></div>${field('Fecha grande (visible a la derecha)',s.settings?.date_label||'14 NOV 2026','settings.date_label')}${field('Hora grande (visible a la derecha)',s.settings?.time_label||'10:00 A. M. · HORA DE CUBA','settings.time_label')}`:''}${s.template==='cta'?`<div class="edit-head"><h3>Tarjeta de Gotas de Felicidad</h3><p>Para mostrarla, crea una tarjeta en la pestaña Tarjetas / elementos. Su título, párrafo y botón se editan allí. Los montos se editan aquí.</p></div>${field('Valores sugeridos (USD), separados por comas',Array.isArray(s.settings?.donation_amounts)?s.settings.donation_amounts.join(','):s.settings?.donation_amounts||'1,3,5','settings.donation_amounts')}`:''}${s.template==='walk'?`<div class="edit-head"><h3>Datos de Camina por Cuba</h3><p>Estos rótulos también son editables.</p></div>${field('Fecha',s.settings?.date_label||'14 NOV 2026','settings.date_label')}${field('Horario',s.settings?.time_label||'10:00 A. M. · HORA DE CUBA','settings.time_label')}${field('Condición de participación',s.settings?.fee_label||'PARTICIPACIÓN GRATUITA','settings.fee_label')}${field('URL del conversor horario',s.settings?.timezone_url||'','settings.timezone_url')}`:''}${initiativeWhatsappFields(s)}<label class="field"><span>Color de fondo y contraste</span><select data-bind="settings.theme">${[['auto','Automático según plantilla'],['cream','Beige claro · texto morado'],['white','Blanco · texto morado'],['purple','Morado · texto blanco'],['dark','Morado noche · texto blanco']].map(([k,v])=>`<option value="${k}" ${((s.settings||{}).theme||'auto')===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Dise\u00f1o / plantilla</span><select data-bind="template">${Object.entries(TEMPLATE_LABELS).map(([v,k])=>`<option value="${v}" ${s.template===v?'selected':''}>${k}</option>`).join('')}</select></label>`:''}${tab==='multimedia'?`${s.section_key==='proposito'?cfAdminPurposeFields(s):''}${s.section_key==='camina'?`<div class="edit-head"><h3>Video destacado · Camina por Cuba</h3><p>Este video aparece encima del párrafo derecho de Camina por Cuba en el Home, no reemplaza los videos de las cinco tarjetas. Puedes subir un MP4/WebM o pegar un enlace de YouTube o Vimeo. El video se reproduce al pulsar sobre la miniatura.</p></div><label class="field"><span>Mostrar la caja del video</span><select data-bind="settings.walk_video_enabled"><option value="true" ${String(s.settings?.walk_video_enabled??'true')!=='false'?'selected':''}>Sí · mostrar</option><option value="false" ${String(s.settings?.walk_video_enabled)==='false'?'selected':''}>No · ocultar</option></select></label>${field('Enlace del video (YouTube, Vimeo, MP4 o WebM)',s.settings?.walk_video?.url||'','settings.walk_video.url')}<label class="field upload-box"><span>Subir archivo de video desde tu equipo</span><input type="file" accept="video/mp4,video/webm" data-upload="settings.walk_video"><small>Archivo de hasta 50 MB. Se almacena en Supabase Storage.</small></label>${field('URL de la miniatura del video (opcional, imagen horizontal 16:9)',s.settings?.walk_video?.poster||'','settings.walk_video.poster')}<label class="field upload-box"><span>Subir miniatura del video</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-upload-poster="settings.walk_video"><small>Recomendado 1280 × 720 píxeles.</small></label><p class="auth-note">Cuando publiques, este espacio se actualizará sin necesidad de cambiar el código. Si aún no hay video, se mostrará una caja de presentación con el título de la iniciativa.</p>`:''}${['camina','proposito'].includes(s.section_key)?'':`<div class="edit-head"><h3>Imagen o video de la secci\u00f3n</h3><p>Admite archivo o URL. Para tarjetas, usa la pesta\u00f1a Tarjetas.</p></div>${s.settings?.shared_fields_from?'<p class="auth-note">La imagen principal se edita en la sección de origen.</p>':mediaFields(s.media||{},'media')}`}`:''}${tab==='tarjetas'?`<div class="edit-head"><h3>${s.section_key==='detail-eligiendo-milagros-2'?'Fotografías y biografías de las facilitadoras':'Elementos de la sección'}</h3><p>${s.section_key==='detail-eligiendo-milagros-2'?'Administra aquí una fotografía para Luzliank, Yonaiky y Verónica. Sube cada archivo y pulsa Publicar cambios para verlo en la web.':'Las tarjetas son parte de esta sección; no son nuevas secciones del sitio.'}</p></div>${s.settings?.shared_items_from?`<div class="sync-note"><b>Las tarjetas proceden de ${t(SOURCE_NAMES[s.settings.shared_items_from]||'la sección principal')}. Cualquier video, portada, texto o botón se actualiza en ambas páginas.</b><button class="control outlined" type="button" data-edit-source="${t(s.settings.shared_items_from)}">Abrir tarjetas originales ↗</button></div>`:`${(s.items||[]).map(cardEditor).join('')}<button class="control outlined full" id="addCard">+ Agregar tarjeta o elemento</button>`}`:''}${tab==='botones'?`<div class="edit-head"><h3>Botones de la secci\u00f3n</h3><p>Edita su texto, destino y estilo sin modificar el c\u00f3digo.</p></div>${buttonsEditor(s.buttons||[],'buttons')}`:''}${tab==='historial'?`<div class="edit-head"><h3>Historial de cambios</h3><p>Se crea una versi\u00f3n cuando guardas los cambios de una secci\u00f3n existente.</p></div><div id="historyList">Cargando historial...</div>`:''}</div><div class="editor-footer"><div class="footer-state">${dirty?'\u25cf Hay cambios sin guardar':'\u2713 Cambios sincronizados'}</div><div class="footer-buttons"><button class="control outlined" id="duplicateSection">\u2398 Clonar</button><button class="control danger" id="removeSection">Eliminar</button><button class="control outlined" id="saveDraft">Guardar como borrador</button><button class="control primary" id="publishSection">Publicar cambios \u2197</button></div></div>`}
function valPath(target,path,value){const parts=path.split('.');let ref=target;for(let i=0;i<parts.length-1;i++){const p=parts[i];if(ref[p]==null)ref[p]=isNaN(Number(parts[i+1]))?{}:[];ref=ref[p]}ref[parts[parts.length-1]]=value;}
function getPath(target,path){return path.split('.').reduce((a,x)=>a?.[x],target)}
function mark(){dirty=true;const el=document.querySelector('.footer-state');if(el)el.textContent='\u25cf Hay cambios sin guardar'}
function bindInputs(){document.querySelectorAll('[data-upload-logo]').forEach(el=>el.onchange=async()=>{const f=el.files?.[0];if(!f)return;el.disabled=true;try{const url=await uploadMedia(f);valPath(activeSection,'settings.logo_url',url);window.CF_LOGO_URL=url;mark();draw();notify('Logo cargado. Pulsa Publicar cambios.')}catch(e){notify(e.message,true);el.disabled=false}});document.querySelectorAll('[data-bind]').forEach(el=>{el.oninput=()=>{if(!activeSection)return;valPath(activeSection,el.dataset.bind,el.value);mark();if(el.dataset.bind.endsWith('.type'))draw()};el.onchange=el.oninput});document.querySelectorAll('[data-upload]').forEach(inp=>inp.onchange=async()=>{const f=inp.files?.[0];if(!f)return;inp.disabled=true;notify('Subiendo archivo...');try{const url=await uploadMedia(f);valPath(activeSection,inp.dataset.upload+'.url',url);valPath(activeSection,inp.dataset.upload+'.type',f.type.startsWith('video/')?'video':'image');mark();draw();notify('Archivo subido a Supabase. Guarda los cambios de la secci\u00f3n.')}catch(e){notify(e.message,true);inp.disabled=false}});document.querySelectorAll('[data-upload-poster]').forEach(inp=>inp.onchange=async()=>{const f=inp.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return notify('La miniatura debe ser una imagen JPG, PNG, WEBP o AVIF.',true);inp.disabled=true;notify('Subiendo miniatura...');try{const url=await uploadMedia(f);valPath(activeSection,inp.dataset.uploadPoster+'.poster',url);mark();draw();notify('Miniatura subida. Pulsa Publicar cambios para verla en la web.')}catch(e){notify(e.message,true);inp.disabled=false}})}

const visibilityBusy=new Set();
async function toggleSectionVisibility(sectionId){
 if(dirty){notify('Guarda primero los cambios sin guardar antes de activar u ocultar una secci\u00f3n.',true);return;}
 if(visibilityBusy.has(sectionId))return;
 const section=sections.find(s=>s.id===sectionId);
 if(!section||!activePage){notify('No se encontr\u00f3 la secci\u00f3n seleccionada.',true);return;}
 const makeVisible=!sectionIsVisible(section);
 const payload={settings:{...(section.settings||{}),show_on_page:makeVisible},updated_at:new Date().toISOString()};
 if(makeVisible&&section.status!=='published')payload.status='published';
 visibilityBusy.add(sectionId);
 const control=document.querySelector('[data-visibility-id="'+sectionId+'"]');
 if(control){control.disabled=true;control.setAttribute('aria-busy','true');}
 try{
  const updated=await mutate('cf_sections','PATCH',payload,'id=eq.'+encodeURIComponent(sectionId)+'&page_id=eq.'+encodeURIComponent(activePage.id));
  if(!Array.isArray(updated)||updated.length!==1)throw Error('No se confirm\u00f3 la actualizaci\u00f3n de esta secci\u00f3n.');
  sections=sections.map(s=>s.id===sectionId?updated[0]:s);
  if(activeSection?.id===sectionId)activeSection=copySection(updated[0]);
  dirty=false;draw();
  notify(makeVisible?'Secci\u00f3n visible en la web. Las otras secciones no cambiaron.':'Secci\u00f3n oculta en la web. Su contenido sigue guardado y las otras secciones no cambiaron.');
 }catch(e){if(control){control.disabled=false;control.removeAttribute('aria-busy');}notify('No se pudo actualizar la visibilidad: '+e.message,true);}
 finally{visibilityBusy.delete(sectionId);}
}
function cfWirePurposeGallery(){
 const add=document.getElementById('addPurposePhoto');
 if(add)add.onclick=()=>{if(!Array.isArray(activeSection.settings.manifesto_gallery))activeSection.settings.manifesto_gallery=cfAdminPurposePhotos(activeSection);activeSection.settings.manifesto_gallery.push({url:'',focal_y:50});mark();draw();};
 document.querySelectorAll('[data-gallery-up],[data-gallery-down],[data-gallery-remove]').forEach(el=>el.onclick=()=>{
  const op=el.dataset.galleryUp!=null?'up':el.dataset.galleryDown!=null?'down':'remove';
  const i=Number(el.dataset['gallery'+op[0].toUpperCase()+op.slice(1)]);
  const arr=activeSection.settings.manifesto_gallery;
  if(!Array.isArray(arr))return;
  if(op==='remove'){if(!confirm('¿Eliminar esta foto del carrusel?'))return;arr.splice(i,1);}
  else{const j=i+(op==='up'?-1:1);if(j>=0&&j<arr.length)[arr[i],arr[j]]=[arr[j],arr[i]];}
  mark();draw();
 });
}
function wire(){cfWirePurposeGallery();document.querySelectorAll('[data-visibility-id]').forEach(el=>el.onclick=()=>toggleSectionVisibility(el.dataset.visibilityId));document.getElementById('editHomeBands')?.addEventListener('click',async()=>{if(dirty&&!confirm('Hay cambios sin guardar. ¿Descartarlos?'))return;const homePage=pages.find(p=>p.slug==='inicio');if(!homePage){notify('No se encuentra Inicio',true);return;}if(activePage?.id!==homePage.id){await loadPage(homePage.id);}const homeSection=sections.find(s=>s.section_key==='home');if(!homeSection){notify('No se encuentra la Portada del Home',true);return;}activeSection=copySection(homeSection);tab='franjas';dirty=false;draw();});document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>loadPage(el.dataset.page));document.querySelectorAll('[data-section]').forEach(el=>el.onclick=()=>{if(dirty&&!confirm('Hay cambios sin guardar. \u00bfDescartarlos?'))return;activeSection=copySection(sections.find(s=>s.id===el.dataset.section));tab=activeSection?.section_key==='home'?'franjas':'contenido';dirty=false;draw()});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;draw();if(tab==='historial')loadHistory()});bindInputs();document.querySelectorAll('[data-edit-source]').forEach(el=>el.onclick=async()=>{const sourceId=el.dataset.editSource;if(dirty&&!confirm('Hay cambios sin guardar. ¿Descartarlos para abrir el contenido original?'))return;try{const result=await query('cf_sections','id=eq.'+sourceId+'&select=id,page_id',{auth:true});if(!result.length)throw new Error('Sección original no disponible');dirty=false;await loadPage(result[0].page_id);activeSection=copySection(sections.find(x=>x.id===sourceId));tab=(activeSection?.items?.length?'tarjetas':'contenido');draw();}catch(err){notify('No fue posible abrir la fuente: '+err.message,true)}});document.getElementById('logout').onclick=async()=>{await authLogout();loginScreen()};document.getElementById('addSection').onclick=addSection;document.getElementById('newPage').onclick=addPage;document.getElementById('savePage').onclick=savePage;document.getElementById('leadView').onclick=showLeads;document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{const [id,d]=el.dataset.move.split(':');moveSection(id,Number(d))});document.querySelectorAll('[data-clone]').forEach(el=>el.onclick=()=>cloneSection(el.dataset.clone));document.getElementById('topSave').onclick=()=>saveSection(null);if(!activeSection)return;document.getElementById('saveDraft').onclick=()=>{if(activeSection?.status==='published'&&!confirm('ATENCIÓN: esto ocultará inmediatamente esta sección del sitio público. ¿Quieres continuar?'))return;saveSection('draft')};document.getElementById('publishSection').onclick=()=>saveSection('published');document.getElementById('duplicateSection').onclick=()=>cloneSection(activeSection.id);document.getElementById('removeSection').onclick=removeSection;document.getElementById('addCard')?.addEventListener('click',()=>{activeSection.items=[...(activeSection.items||[]),{title:'Nueva tarjeta',body:'',media:{type:'image',url:''},buttons:[]}];mark();draw()});document.querySelectorAll('[data-clear-mentor-photo]').forEach(button=>button.onclick=()=>{
  if(!activeSection||activeSection.section_key!=='detail-eligiendo-milagros-2')return;
  const index=Number(button.dataset.clearMentorPhoto);
  const item=activeSection.items?.[index];
  if(!item)return;
  if(!confirm('¿Quitar la fotografía de '+(item.title||'esta facilitadora')+'? El cambio aparecerá cuando publiques.'))return;
  item.media={...(item.media||{}),type:'image',url:''};
  mark();draw();
});
document.querySelectorAll('[data-card-up],[data-card-down],[data-card-clone],[data-card-remove]').forEach(el=>el.onclick=()=>{const op=el.dataset.cardUp!=null?'up':el.dataset.cardDown!=null?'down':el.dataset.cardClone!=null?'clone':'remove';const i=Number(el.dataset['card'+op[0].toUpperCase()+op.slice(1)]);const a=activeSection.items;if(op==='up'&&i>0)[a[i-1],a[i]]=[a[i],a[i-1]];if(op==='down'&&i<a.length-1)[a[i+1],a[i]]=[a[i],a[i+1]];if(op==='clone')a.splice(i+1,0,JSON.parse(JSON.stringify(a[i])));if(op==='remove'&&confirm('Eliminar esta tarjeta?'))a.splice(i,1);mark();draw()});document.querySelectorAll('[data-add-button]').forEach(el=>el.onclick=()=>{const arr=getPath(activeSection,el.dataset.addButton);arr.push({label:'Nuevo bot\u00f3n',href:'#participar',style:'primary'});mark();draw()});document.querySelectorAll('[data-remove-button]').forEach(el=>el.onclick=()=>{const [path,index]=el.dataset.removeButton.split(':');getPath(activeSection,path).splice(Number(index),1);mark();draw()});document.querySelectorAll('[data-move-button]').forEach(el=>el.onclick=()=>{const [path,index,d]=el.dataset.moveButton.split(':');const arr=getPath(activeSection,path),i=Number(index),j=i+Number(d);if(j>=0&&j<arr.length){[arr[i],arr[j]]=[arr[j],arr[i]];mark();draw()}})}
const allowedFields=['section_key','template','title','eyebrow','subtitle','body','media','items','buttons','settings','sort_order','status'];
const extract=s=>Object.fromEntries(allowedFields.map(k=>[k,s[k]]));
async function saveSection(status){if(!activeSection)return;try{const original=sections.find(s=>s.id===activeSection.id);if(!original)throw Error('Secci\u00f3n no seleccionada');const before=await query('cf_sections','select=*&id=eq.'+activeSection.id,{auth:true});const snapshot=extract(before[0]||activeSection);await mutate('cf_revisions','POST',{section_id:activeSection.id,snapshot,editor_id:getSession().user.id},'',{returning:false});const update=extract(activeSection);if(status)update.status=status;const x=await mutate('cf_sections','PATCH',{...update,updated_at:new Date().toISOString()},'id=eq.'+activeSection.id);sections=sections.map(s=>s.id===activeSection.id?x[0]:s);activeSection=copySection(x[0]);dirty=false;draw();notify(status==='published'?'Secci\u00f3n publicada correctamente':'Cambios guardados en Supabase')}catch(e){notify('Error al guardar: '+e.message,true)}}
async function addSection(){if(dirty&&!confirm('Hay cambios sin guardar. Continuar?'))return;const choice=prompt('Plantilla: hero, manifesto, walk, cards, quote, split, cta, donations, faq, content','split');if(!choice)return;if(!TEMPLATE_LABELS[choice])return notify('Plantilla no disponible',true);const name=prompt('Nombre de la nueva secci\u00f3n','Nueva secci\u00f3n');if(!name)return;try{const payload={page_id:activePage.id,section_key:key(name)+'-'+Date.now().toString(36),template:choice,title:name,eyebrow:'',subtitle:'',body:'',media:{type:'image',url:''},items:[],buttons:[],settings:{},sort_order:sections.length?Math.max(...sections.map(x=>x.sort_order))+10:0,status:'draft'};const x=await mutate('cf_sections','POST',payload);sections.push(x[0]);activeSection=copySection(x[0]);tab='contenido';dirty=false;draw();notify('Secci\u00f3n creada en borrador')}catch(e){notify(e.message,true)}}
async function cloneSection(sectionId){if(dirty&&!confirm('Hay cambios sin guardar. Continuar?'))return;try{const src=sections.find(s=>s.id===sectionId);const name=src.title+' (copia)';const o={...extract(src),page_id:activePage.id,section_key:src.section_key+'-copia-'+Date.now().toString(36),title:name,sort_order:src.sort_order+1,status:'draft'};const x=await mutate('cf_sections','POST',o);await reorderForInsert(x[0]);activeSection=copySection(x[0]);tab='contenido';dirty=false;draw();notify('Secci\u00f3n clonada como borrador')}catch(e){notify(e.message,true)}}
async function reorderForInsert(item){const ordered=[...sections].sort((a,b)=>a.sort_order-b.sort_order);let i=ordered.findIndex(x=>x.sort_order>=item.sort_order);if(i<0)i=ordered.length;ordered.splice(i,0,item);await Promise.all(ordered.map((x,k)=>mutate('cf_sections','PATCH',{sort_order:k*10},'id=eq.'+x.id,{returning:false})));sections=ordered.map((x,k)=>({...x,sort_order:k*10}))}
async function moveSection(sectionId,delta){if(dirty)return notify('Guarda primero los cambios actuales',true);const i=sections.findIndex(s=>s.id===sectionId),j=i+delta;if(i<0||j<0||j>=sections.length)return;[sections[i],sections[j]]=[sections[j],sections[i]];try{await Promise.all(sections.map((s,k)=>mutate('cf_sections','PATCH',{sort_order:k*10},'id=eq.'+s.id,{returning:false})));sections=sections.map((s,k)=>({...s,sort_order:k*10}));draw();notify('Orden actualizado')}catch(e){notify(e.message,true)}}
async function removeSection(){if(!confirm('Esta acci\u00f3n elimina la secci\u00f3n y su historial. \u00bfContinuar?'))return;try{await mutate('cf_sections','DELETE',null,'id=eq.'+activeSection.id,{returning:false});sections=sections.filter(s=>s.id!==activeSection.id);activeSection=copySection(sections[0]||null);dirty=false;draw();notify('Secci\u00f3n eliminada')}catch(e){notify(e.message,true)}}
async function savePage(){const title=document.getElementById('pageTitle').value.trim(),status=document.getElementById('pageStatus').value,show_in_nav=document.getElementById('pageNav').checked;if(!title)return notify('El nombre es obligatorio',true);try{const x=await mutate('cf_pages','PATCH',{title,status,show_in_nav,updated_at:new Date().toISOString()},'id=eq.'+activePage.id);pages=pages.map(p=>p.id===activePage.id?x[0]:p);activePage=x[0];draw();notify('P\u00e1gina actualizada')}catch(e){notify(e.message,true)}}
async function addPage(){const title=prompt('Nombre de la p\u00e1gina nueva');if(!title)return;const slug=key(title);if(!slug)return;try{const x=await mutate('cf_pages','POST',{title,slug,status:'draft',show_in_nav:false,sort_order:pages.length*10});pages.push(x[0]);loadPage(x[0].id)}catch(e){notify('No se pudo crear la p\u00e1gina: '+e.message,true)}}
async function loadHistory(){try{const xs=await query('cf_revisions','select=*&section_id=eq.'+activeSection.id+'&order=created_at.desc&limit=12',{auth:true});document.getElementById('historyList').innerHTML=xs.length?xs.map(x=>`<div class="revision"><div><b>${new Date(x.created_at).toLocaleString('es-ES')}</b><small>${t(x.snapshot?.title)}</small></div><button data-restore="${x.id}" class="control outlined">Restaurar</button></div>`).join(''):'Todav\u00eda no hay revisiones';document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restaurar esta versi\u00f3n?'))return;const rec=xs.find(x=>String(x.id)===b.dataset.restore);Object.assign(activeSection,rec.snapshot);mark();tab='contenido';draw();notify('Versi\u00f3n cargada. Guarda para aplicar los cambios.')})}catch(e){document.getElementById('historyList').textContent='No fue posible cargar el historial: '+e.message}}
async function showLeads(){if(dirty&&!confirm('Hay cambios sin guardar. Continuar?'))return;try{allLeads=await query('cf_leads','select=full_name,country,phone,email,interest,created_at&order=created_at.desc&limit=200',{auth:true});document.querySelector('.editor-layout').innerHTML=`<div class="leads-page"><h2>Inscripciones y personas interesadas</h2><p>${allLeads.length} registros m\u00e1s recientes. Los datos son privados.</p><table><thead><tr><th>Fecha</th><th>Nombre</th><th>Pa\u00eds</th><th>Contacto</th><th>Inter\u00e9s</th></tr></thead><tbody>${allLeads.map(x=>`<tr><td>${new Date(x.created_at).toLocaleDateString('es-ES')}</td><td>${t(x.full_name)}</td><td>${t(x.country)}</td><td>${t(x.phone||x.email)}</td><td>${t(x.interest)}</td></tr>`).join('')}</tbody></table><button id="backToEditor" class="control outlined">\u2190 Volver al editor</button></div>`;document.getElementById('backToEditor').onclick=draw;}catch(e){notify(e.message,true)}}
window.CF_BIZ_API={query,mutate,getSession,draw,app};
window.CF_START_ADMIN=function(){if(getSession())loadAdmin();else loginScreen();};

})();
